import org.apache.nifi.serialization.record.*
import java.io.ByteArrayOutputStream
import java.net.URLDecoder

flowFile = session.get()
if (!flowFile) return

def reader = context.controllerServiceLookup.getControllerService(
        flowFile.getAttribute("record.reader.id")
)
def writer = context.controllerServiceLookup.getControllerService(
        flowFile.getAttribute("record.writer.id")
)

def outStream = new ByteArrayOutputStream()
def recordReader = reader.createRecordReader(flowFile, session.read(flowFile), logger)
def recordWriter = writer.createRecordWriter(recordReader.getSchema(), outStream, logger)

recordWriter.beginRecordSet()

Record record
while ((record = recordReader.nextRecord()) != null) {

    def html = record.getValue("ReportContent")
    if (html != null) {
        String text = html.toString()

        // 1. decode entity cơ bản
        text = text.replace("&nbsp;", " ")
                   .replace("&lt;", "<")
                   .replace("&gt;", ">")
                   .replace("&amp;", "&")
                   .replace("&quot;", "\"")
                   .replace("&#39;", "'")

        // 2. remove HTML tags
        text = text.replaceAll("<[^>]+>", " ")

        // 3. normalize space
        text = text.replaceAll("\\s+", " ").trim()

        record.setValue("ReportContent", text)
    }

    recordWriter.write(record)
}

recordWriter.finishRecordSet()
recordReader.close()
recordWriter.close()

flowFile = session.write(flowFile, { out ->
    out.write(outStream.toByteArray())
} as OutputStreamCallback)

session.transfer(flowFile, REL_SUCCESS)

